// Turns a form or website submission into one tidy lead. Field names are matched loosely,
// so "Email", "email" and "e-mail" all count, and a website can post its own names.
const trigger = $('Enquiry form').isExecuted
  ? $('Enquiry form').first().json
  : $('Website form').first().json;
// The webhook puts the posted fields under "body"; the form puts them at the top level.
const fromWebsite = trigger.body !== undefined && trigger.headers !== undefined;
const fields = fromWebsite && trigger.body && typeof trigger.body === 'object' ? trigger.body : trigger;

const lookup = {};
for (const [key, value] of Object.entries(fields)) {
  lookup[key.toLowerCase().replace(/[^a-z]/g, '')] = value;
}
const pick = (...names) => {
  for (const name of names) {
    const value = lookup[name];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
  }
  return '';
};
const clip = (text, max) => (text.length > max ? text.slice(0, max) + '...' : text);

const email = pick('email', 'emailaddress', 'youremail').toLowerCase();

return [{
  json: {
    name: clip(pick('name', 'fullname', 'yourname', 'firstname'), 120),
    email: clip(email, 200),
    emailLooksValid: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email),
    phone: clip(pick('phone', 'phonenumber', 'mobile', 'tel', 'telephone'), 40),
    service: clip(pick('serviceneeded', 'service', 'services', 'subject', 'interest'), 200),
    message: clip(pick('message', 'enquiry', 'inquiry', 'comments', 'details'), 3000),
    source: fromWebsite ? 'website' : 'form',
    receivedAt: $now.toISO(),
    receivedMs: Date.now(),
  },
}];

