// Reads the spam check's answer. If OpenAI could not be reached or gave an odd answer, the
// enquiry is marked "unchecked": it gets no automatic reply, and the owner is asked to reply.
const lead = $('Tidy the enquiry').first().json;
const response = $input.first().json;

let label = 'unchecked';
let reason = 'The spam check did not give an answer.';
let labelSource = 'none';
try {
  const parsed = JSON.parse(response.choices[0].message.content);
  const value = String(parsed.label || '').toLowerCase().trim();
  if (value === 'spam' || value === 'real') {
    label = value;
    reason = String(parsed.reason || '').slice(0, 200);
    labelSource = 'model';
  }
} catch (error) {
  // Leave it as unchecked.
}

let route = label === 'spam' ? 'spam' : label === 'real' ? 'reply' : 'person';
let personReason = label === 'unchecked' ? 'the spam check failed' : '';
if (route === 'reply' && !lead.emailLooksValid) {
  route = 'person';
  personReason = 'there is no valid email address to reply to';
}

return [{
  json: { ...lead, label, spamReason: reason, labelSource, route, personReason, spamCheckUsage: response.usage || null },
}];

// Looks in the log for an earlier reply to the same email address inside the window set in
// Settings. Only rows that got a reply (sent or draft) count, so an earlier spam row never
// blocks a real enquiry. If the sheet could not be read, the enquiry is treated as new.
const lead = $('Read the spam check').first().json;
const hours = Number($('Settings').first().json.duplicateWindowHours) || 24;
const since = Date.now() - hours * 3600 * 1000;

let earlierReplyAt = '';
for (const item of $input.all()) {
  const row = item.json || {};
  if (row.error) continue;
  const email = String(row['Email'] || '').trim().toLowerCase();
  const reply = String(row['Reply'] || '').trim().toLowerCase();
  const time = Date.parse(row['Time']);
  if (email && email === lead.email && (reply === 'sent' || reply === 'draft') && time >= since) {
    earlierReplyAt = String(row['Time']);
  }
}

return [{ json: { ...lead, isRepeat: earlierReplyAt !== '', earlierReplyAt } }];

// Checks the AI reply before it can reach a customer. If the reply is missing, too short or too
// long, mentions a price, a date, a time or availability, or holds any link other than the
// booking link or any email address, a plain fixed reply is used instead.
const lead = $('Replied in the last 24 hours?').first().json;
const settings = $('Settings').first().json;
const response = $input.first().json;

const firstName = (String(lead.name).trim().split(/\s+/)[0] || '').replace(/[^\p{L}'-]/gu, '').slice(0, 30) || 'there';
const service = String(lead.service)
  .replace(/https?:\/\/\S+|www\.\S+|\S+@\S+/gi, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 60);

let body = '';
try {
  body = String(JSON.parse(response.choices[0].message.content).body || '').trim();
} catch (error) {
  body = '';
}

// The booking link is required. If the model left it out, add it rather than throw the reply away.
if (body && !body.includes(settings.bookingLink)) {
  body += '\n\nYou can pick a time to talk here: ' + settings.bookingLink;
}

const risky = [
  // Amounts of money and rates.
  /[$\u20ac\u00a3\u00a5]\s?\d/,
  /\b\d[\d,.]*\s?(k|dollars?|aud|usd|nzd|gbp|eur)\b/i,
  /\b\d[\d,.]*\s?(per|an|a)\s(hour|hr|day|week|month|job)\b/i,
  /\b\d+\s?%/,
  // Free or cut-price offers.
  /\b(no charge|no cost|at no cost|discount\w*|special offer|cheapest|lowest price|best price|affordable|competitive (rates|prices|pricing))\b/i,
  // Days, dates and times.
  /\b(today|tonight|tomorrow|this (morning|afternoon|evening|week|weekend|month)|next (week|month)|weekend|asap|straight away|right away|same[- ]day)\b/i,
  /\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|january|february|march|april|june|july|august|september|october|november|december)\b/i,
  /\b\d{1,2}(:\d{2})?\s?(am|pm)\b/i,
  /\b\d{1,2}:\d{2}\b/,
  /\b\d{1,2}(st|nd|rd|th)\b/i,
  /\b\d{1,2}\/\d{1,2}\b/,
  // Timeframes and response times.
  /\bwithin\b/i,
  /\b\d+\s?(-\s?\d+\s?)?(minutes?|mins?|hours?|hrs?|days?|weeks?|months?)\b/i,
  /\b(in|within|over|for|about|take|takes|taking) (a|one|two|three|a few|a couple of) (minutes?|hours?|days?|weeks?)\b/i,
  /\bby the end of\b/i,
  // Money, however it is written.
  /\b(dollars?|bucks|cents)\b/i,
  /\b(cost|costs|costing|price|priced|charge|charges|fee|fees|rate|rates|budget)\b[^.!?\n]{0,40}\b(\d|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|grand)/i,
  // Free offers. "Feel free to" is fine.
  /\b(?<!feel )free\b(?! to\b)/i,
  /\bon the house\b/i,
  // Times and timeframes written in words.
  /\b(fortnight|noon|midday|midnight|overnight|first thing)\b/i,
  // Web addresses without http or www.
  /\b[a-z0-9-]+\.(com|net|org|au|nz|uk|io|co|dev|app|biz|info|me|ai)\b/i,
  // Availability.
  /\b(availab\w*|can start|start (straight away|immediately|next)|fit you in|book you in|openings?|guarantee\w*|promise\w*)\b/i,
];
const links = body.match(/https?:\/\/[^\s)>\]]+|www\.[^\s)>\]]+/gi) || [];
const otherLink = links.some((link) => link.replace(/[.,;:!?]+$/, '') !== settings.bookingLink);
const bodyWithoutLink = body.split(settings.bookingLink).join(' ');

const problems = [];
if (body.length < 40) problems.push('missing or too short');
if (body.length > 1500) problems.push('too long');
if (risky.some((pattern) => pattern.test(bodyWithoutLink))) problems.push('mentions a price, date, time or availability');
if (otherLink) problems.push('holds a link other than the booking link');
if (/[^\s@]+@[^\s@]+\.[^\s@]+/.test(bodyWithoutLink)) problems.push('holds an email address');

const fixedReply =
  'Hi ' + firstName + ',\n\n' +
  'Thanks for getting in touch with ' + settings.businessName + (service ? ' about ' + service : '') + '. ' +
  "We've got your message and will get back to you personally.\n\n" +
  'If it suits you, you can pick a time to talk here: ' + settings.bookingLink + '\n\n' +
  'Kind regards,\n' + settings.businessName;

return [{
  json: {
    ...lead,
    replySubject: 'Thanks for getting in touch with ' + settings.businessName,
    replyBody: problems.length ? fixedReply : body,
    replySource: problems.length ? 'fixed' : 'model',
    replyProblems: problems.join('; '),
    replyUsage: response.usage || null,
  },
}];

// Records how long the customer waited. The clock started when the enquiry arrived and stops
// as soon as Gmail confirms the reply was sent or saved as a draft.
const lead = $('Check the reply').first().json;
const result = $input.first().json;
const draftOnly = ['true', 'yes', '1'].includes(String($('Settings').first().json.DRAFT_ONLY).toLowerCase());
const failed = Boolean(result.error) || !result.id;
const seconds = Math.round((Date.now() - lead.receivedMs) / 100) / 10;
const status = failed ? 'failed' : draftOnly ? 'draft' : 'sent';

return [{
  json: {
    ...lead,
    replyStatus: status,
    alertKind: status,
    replyError: failed ? String((result.error && result.error.message) || result.error || 'Gmail returned no message id') : '',
    secondsToReply: failed ? '' : seconds,
    gmailId: result.id || '',
  },
}];

// Writes the owner's alert. The email gets the full details; SMS and Telegram get a short
// version, if you switch those nodes on.
const lead = $input.first().json;
const settings = $('Settings').first().json;
const oneLine = (text, max) => String(text || '').replace(/\s+/g, ' ').trim().slice(0, max);
const hours = Number(settings.duplicateWindowHours) || 24;

const outcome = {
  sent: 'Auto-reply sent in ' + lead.secondsToReply + ' seconds.',
  draft: 'Auto-reply saved as a Gmail draft. Check it, then press send.',
  failed: 'The auto-reply failed (' + oneLine(lead.replyError, 200) + '). Please reply yourself.',
  repeat: 'No auto-reply: this address already had one in the last ' + hours + ' hours.',
  person: 'No auto-reply, because ' + (lead.personReason || 'it needs a person') + '. Please reply yourself.',
}[lead.alertKind] || '';
const heading = {
  sent: 'New lead',
  draft: 'New lead',
  failed: 'New lead, reply failed',
  repeat: 'Repeat enquiry',
  person: 'Lead needs you',
}[lead.alertKind] || 'New lead';

const subject = heading + ': ' + (oneLine(lead.name, 60) || 'no name') + (lead.service ? ' | ' + oneLine(lead.service, 60) : '');
const body = [
  heading + ' for ' + settings.businessName,
  '',
  'Name: ' + (lead.name || '-'),
  'Email: ' + (lead.email || '-'),
  'Phone: ' + (lead.phone || '-'),
  'Service: ' + (lead.service || '-'),
  'Came in: ' + lead.receivedAt + ' (' + lead.source + ')',
  '',
  'Message:',
  lead.message || '-',
  '',
  outcome,
].join('\n');
const short = oneLine(heading + ': ' + (lead.name || 'no name') + ', ' + (lead.phone || lead.email) + '. ' + (lead.service || '') + ' ' + outcome, 300);

return [{ json: { ...lead, alertSubject: subject, alertBody: body, alertShort: short } }];

// One row for the log sheet. A blank sheet gets these column names as its first row the
// first time a lead comes in. Keep the names as they are: the duplicate check reads them.
const lead = $input.first().json;
return [{
  json: {
    'Time': lead.receivedAt,
    'Name': lead.name,
    'Email': lead.email,
    'Phone': lead.phone,
    'Service': lead.service,
    'Message': lead.message,
    'Spam or real': lead.label,
    'Reply': lead.replyStatus,
    'Seconds to reply': lead.secondsToReply,
  },
}];
